local PoultryKeeper = {}
local PRODUCTS = {
    egg_hen = { name = "Nesnica", henCost = 1, grainCost = 1, waterCost = 1, time = 2, cost = 14, yield = 35, happiness = 1, description = "Nesnica za proizvodnjo jajc." },
    capon = { name = "Kastriran petelin", henCost = 1, grainCost = 1, waterCost = 1, time = 3, cost = 22, yield = 45, prestige = 1, description = "Kastriran petelin za meso." },
    goose = { name = "Gos", gooseCost = 1, grainCost = 1, waterCost = 1, time = 4, cost = 35, yield = 50, prestige = 2, happiness = 1, description = "Gos za jetra in perje." },
    silver_feathered_fowl = { name = "Srebrno pernata perutnina", gooseCost = 1, silverCost = 1, grainCost = 1, waterCost = 1, time = 7, cost = 120, yield = 70, prestige = 7, happiness = 2, description = "Srebrno pernata perutnina za plemiče." },
    silver_bell_coop = { name = "Srebrno zvončni kurnik", henCost = 2, silverCost = 1, grainCost = 2, waterCost = 1, time = 10, cost = 320, yield = 85, prestige = 13, happiness = 3, description = "Kurnik s srebrnimi zvoni za visoke plemiče." },
    royal_grand_aviary = { name = "Kraljevski veliki ptičnica", henCost = 3, gooseCost = 2, goldCost = 1, silverCost = 1, jewelCost = 1, grainCost = 3, waterCost = 2, time = 15, cost = 1400, yield = 100, prestige = 34, happiness = 8, description = "Velika kraljevska ptičnica z zlatom in dragulji za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Perutninska postaja", cost = { gold = 200, wood = 110, stone = 150 }, upkeep = 4, qualityBonus = 5 },
    poultry_yard = { name = "Perutninski dvori", cost = { gold = 700, wood = 200, stone = 250, grain = 10 }, upkeep = 17, qualityBonus = 18 },
    egg_house = { name = "Jajčna hiša", cost = { gold = 1800, wood = 300, stone = 500, silver = 25, iron = 6 }, upkeep = 45, qualityBonus = 30 },
    royal_poultry_atelier = { name = "Kraljevski atelje perutnine", cost = { gold = 7500, wood = 500, stone = 900, gold = 60, jewel = 20 }, upkeep = 150, qualityBonus = 55, prestigeBonus = 40 },
}
PoultryKeeper.henStock = 24; PoultryKeeper.gooseStock = 16; PoultryKeeper.grainStock = 22; PoultryKeeper.waterStock = 18; PoultryKeeper.silverStock = 8; PoultryKeeper.goldStock = 6; PoultryKeeper.jewelStock = 6
PoultryKeeper.productStock = {}; PoultryKeeper.buildings = {}; PoultryKeeper.maker = nil; PoultryKeeper.activeMaking = {}; PoultryKeeper.totalProducts = 0; PoultryKeeper.dayTimer = 0
function PoultryKeeper.init() PoultryKeeper.henStock=24; PoultryKeeper.gooseStock=16; PoultryKeeper.grainStock=22; PoultryKeeper.waterStock=18; PoultryKeeper.silverStock=8; PoultryKeeper.goldStock=6; PoultryKeeper.jewelStock=6; PoultryKeeper.productStock={}; PoultryKeeper.buildings={}; PoultryKeeper.maker=nil; PoultryKeeper.activeMaking={}; PoultryKeeper.totalProducts=0; PoultryKeeper.dayTimer=0; print("[PoultryKeeper] Royal Poultry Keeper System initialized (6 products, 4 buildings)") end
function PoultryKeeper.hireMaker(n,s) s=s or math.random(45,85); local c=440+s*10; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; PoultryKeeper.maker={name=n or ("Perutninar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Perutninar najet: %s (spretnost: %d)",PoultryKeeper.maker.name,s),"success") end; return true end
function PoultryKeeper.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function PoultryKeeper.build(id) local ok,e=PoultryKeeper.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(PoultryKeeper.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function PoultryKeeper.getQualityBonus() local b=0; for _,bd in ipairs(PoultryKeeper.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function PoultryKeeper.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.henCost and PoultryKeeper.henStock<(d.henCost or 0) then return false,"Premalo kokli" end; if d.gooseCost and PoultryKeeper.gooseStock<(d.gooseCost or 0) then return false,"Premalo gosi" end; if d.grainCost and PoultryKeeper.grainStock<(d.grainCost or 0) then return false,"Premalo žita" end; if d.waterCost and PoultryKeeper.waterStock<(d.waterCost or 0) then return false,"Premalo vode" end; if d.silverCost and PoultryKeeper.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and PoultryKeeper.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and PoultryKeeper.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if #PoultryKeeper.buildings==0 then return false,"Potrebna delavnica" end; if not PoultryKeeper.maker then return false,"Potreben perutninar" end; return true end
function PoultryKeeper.make(pt,qty) qty=qty or 5; local ok,e=PoultryKeeper.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.henCost then PoultryKeeper.henStock=PoultryKeeper.henStock-d.henCost*qty end; if d.gooseCost then PoultryKeeper.gooseStock=PoultryKeeper.gooseStock-d.gooseCost*qty end; if d.grainCost then PoultryKeeper.grainStock=PoultryKeeper.grainStock-d.grainCost*qty end; if d.waterCost then PoultryKeeper.waterStock=PoultryKeeper.waterStock-d.waterCost*qty end; if d.silverCost then PoultryKeeper.silverStock=PoultryKeeper.silverStock-d.silverCost*qty end; if d.goldCost then PoultryKeeper.goldStock=PoultryKeeper.goldStock-d.goldCost*qty end; if d.jewelCost then PoultryKeeper.jewelStock=PoultryKeeper.jewelStock-d.jewelCost*qty end; local t=d.time; if PoultryKeeper.maker then t=math.max(1,t-math.floor(PoultryKeeper.maker.skill/12)) end; table.insert(PoultryKeeper.activeMaking,{id="poultry_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,yield=d.yield or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function PoultryKeeper.completeMaking(m) local q=1.0+(PoultryKeeper.getQualityBonus()/100); if PoultryKeeper.maker then q=q+(PoultryKeeper.maker.skill/180) end; q=math.min(2.0,q); PoultryKeeper.productStock[m.productType]=(PoultryKeeper.productStock[m.productType] or 0)+m.quantity; PoultryKeeper.totalProducts=PoultryKeeper.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if PoultryKeeper.maker then PoultryKeeper.maker.itemsMade=PoultryKeeper.maker.itemsMade+m.quantity; if math.random()<0.20 then PoultryKeeper.maker.skill=math.min(100,PoultryKeeper.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Perutnina vzrejena: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"poultry.completed",{productName=m.productName,yield=m.yield,happiness=m.happiness}) end end
function PoultryKeeper.update(dt) if not _G.state then return end; PoultryKeeper.dayTimer=PoultryKeeper.dayTimer+dt; if PoultryKeeper.dayTimer>=30 then PoultryKeeper.dayTimer=0; for i=#PoultryKeeper.activeMaking,1,-1 do local m=PoultryKeeper.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then PoultryKeeper.completeMaking(m); table.remove(PoultryKeeper.activeMaking,i) end end; local tu=0; for _,bd in ipairs(PoultryKeeper.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if PoultryKeeper.maker then tu=tu+11 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function PoultryKeeper.getStats() return {henStock=PoultryKeeper.henStock,gooseStock=PoultryKeeper.gooseStock,grainStock=PoultryKeeper.grainStock,waterStock=PoultryKeeper.waterStock,silverStock=PoultryKeeper.silverStock,goldStock=PoultryKeeper.goldStock,jewelStock=PoultryKeeper.jewelStock,productStock=PoultryKeeper.productStock,numBuildings=#PoultryKeeper.buildings,hasMaker=PoultryKeeper.maker~=nil,makerName=PoultryKeeper.maker and PoultryKeeper.maker.name or "—",makerSkill=PoultryKeeper.maker and PoultryKeeper.maker.skill or 0,activeMaking=#PoultryKeeper.activeMaking,totalProducts=PoultryKeeper.totalProducts} end
return PoultryKeeper
